def one_lot_per_purchase(apps, schema_editor):
    """Each goods receipt (port purchases make one too) becomes one lot, its batches the lines in receipt order; any
    other batch becomes a lot of its own. A lot takes its first line's number, so every number printed so far still
    finds its lot, and the lines keep theirs (D-310)."""
    Batch = apps.get_model("inventory", "Batch")
    Lot = apps.get_model("inventory", "Lot")
    ReceiptLine = apps.get_model("purchasing", "GoodsReceiptLine")
    by_receipt: dict[int, list[int]] = {}
    for receipt_id, batch_id in ReceiptLine.objects.order_by("receipt_id", "id").values_list("receipt_id", "batch_id"):
        by_receipt.setdefault(receipt_id, []).append(batch_id)
    batches = {batch.pk: batch for batch in Batch.objects.all()}

    def new_lot(first):
        return Lot.objects.create(
            organization_id=first.organization_id,
            number=first.number,
            supplier_id=first.supplier_id,
            received_on=first.received_on,
            receipt_reference=first.receipt_reference,
        )

    for batch_ids in by_receipt.values():
        lot = new_lot(batches[batch_ids[0]])
        for line_number, batch_id in enumerate(batch_ids, start=1):
            batch = batches.pop(batch_id)
            batch.lot = lot
            batch.line_number = line_number
            batch.save(update_fields=["lot", "line_number"])
    for batch in batches.values():
        batch.lot = new_lot(batch)
        batch.line_number = 1
        batch.save(update_fields=["lot", "line_number"])


